@dataclass(frozen=True)
class LegacyQuote:                 # exactly the shape the old client sends
    SKU: str
    unit_price: str                # decimal as text, never a float
    ccy: str = "EUR"

def from_legacy(dto: LegacyQuote) -> Quote:
    return Quote(sku=dto.SKU, currency=dto.ccy,
                 cents=(Decimal(dto.unit_price) * 100).to_integral_value())

def to_legacy(q: Quote) -> LegacyQuote:
    return LegacyQuote(SKU=q.sku, ccy=q.currency,
                       unit_price=str((q.cents / 100).quantize(CENTS)))
